    size = len(matrix)
    if size != len(matrix[0]):
        return False
    ref_sum = sum(matrix[0])

    # Check rows and columns against the reference sum
    for row in matrix:
        if sum(row) != ref_sum:
            return False
    for col in range(size):
        if sum(row[col] for row in matrix) != ref_sum:
            return False

    # Check diagonals
    if sum(matrix[i][i] for i in range(size)) != ref_sum:
        return False
    if sum(matrix[i][size-i-1] for i in range(size)) != ref_sum:
        return False

    return True

