def pancake_sort(arr):
    def flip(sublist, k):
        sublist[:k] = sublist[:k][::-1]

    def find_max_index(arr, n):
        max_index = 0
        for i in range(1, n):
            if arr[i] > arr[max_index]:
                max_index = i
        return max_index

    n = len(arr)
    while n > 1:
        max_index = find_max_index(arr, n)
        if max_index != n - 1:
            flip(arr, max_index + 1)
            flip(arr, n)
        n -= 1
    return arr

