    :param s: Input string
    :return: Length of the longest palindromic subsequence
    """
    # Remove spaces and convert to lowercase for uniformity
    s = s.replace(" ", "").lower()

    def longest_palindromic_subseq(s, i, j):
        if i > j:
            return 0
        elif i == j:
            return 1
        elif s[i] == s[j]:
            return 2 + longest_palindromic_subseq(s, i+1, j-1)
        else:
            return max(longest_palindromic_subseq(s, i+1, j), longest_palindromic_subseq(s, i, j-1))

    # Adjust the function to correctly handle overlapping subproblems
    memo = {}
    def memoized_lps(s, i, j):
        if (i, j) in memo:
            return memo[(i, j)]
        if i > j:
            return 0
        elif i == j:
            return 1
        elif s[i] == s[j]:
            memo[(i, j)] = 2 + memoized_lps(s, i+1, j-1)
        else:
            memo[(i, j)] = max(memoized_lps(s, i+1, j), memoized_lps(s, i, j-1))
        return memo[(i, j)]

    return memoized_lps(s, 0, len(s) - 1)

