def combinations_list(lst):
    from itertools import chain, combinations

    def all_combinations(elements):
        return list(chain.from_iterable(combinations(elements, r) for r in range(len(elements)+1)))

    # Ensure the combination lists are sorted and maintain the order of elements as they appear in the input list
    def sort_combinations(combs, lst):
        return sorted(combs, key=lambda x: ([lst.index(i) for i in x if i in lst], len(x)))

    # Convert each combination from an iterable to a list for consistent ordering
    return sort_combinations([list(comb) for comb in all_combinations(lst)], lst)

